import {CONTROLS, POLICY, FINDING_TYPES} from './engine.mjs';

export function createPillarViews(context) {
  const {engine,ui,esc,icon,badge,provider,time,date,button,empty,pageHeader,openDialog,closeDialog,navigate,toast,render,policies,evidence} = context;
  const activeEnvs=()=>engine.environments.filter(e=>e.lifecycle==='Active');
  const unresolved=f=>['Open','In progress'].includes(f.status);
  const severity=s=>badge(s,s==='Critical'?'red':s==='High'?'amber':'gray');
  const due=timestamp=>timestamp<=engine.now()?`<span class="due-overdue">Overdue</span>`:`${date(timestamp)} · ${time(timestamp).slice(0,5)} UTC`;
  const duration=value=>value===null?'—':value<1?'<1':Math.round(value).toLocaleString();
  const envOptions=(selected,all=false)=>(all?'<option value="all">All environments</option>':'')+activeEnvs().map(e=>`<option value="${e.id}" ${selected===e.id?'selected':''}>${esc(e.name)} · ${esc(e.provider)}</option>`).join('');
  const subnav=(name,selected,items)=>`<nav class="pillar-tabs" aria-label="${name==='assurance'?'Assurance':'Governance'} views">${items.map(([key,title,count])=>`<a href="#${name}/${key}" ${selected===key?'aria-current="page"':''}>${title}${count===undefined?'':`<span>${count}</span>`}</a>`).join('')}</nav>`;
  const stat=(label,value,note,ico)=>`<article class="metric-card"><div class="metric-label">${label}${icon(ico)}</div><div class="metric-value">${value}</div><p class="metric-note">${note}</p></article>`;
  const auditButton=id=>button('Evidence','session-evidence','secondary','evidence',`data-id="${id}"`);
  const findingLink=f=>`<button class="finding-link" data-action="finding" data-id="${f.id}"><b>${esc(f.title)}</b><small>${f.id} · ${esc(f.category)}</small></button>`;
  function assurance() {
    const m=engine.assuranceMetrics();
    return `${pageHeader('PILLAR 03 / STAY TRUSTED','Cloud Assurance','Keep each workload trusted through change, remediation, and retirement.',button('Run posture scan','scan','secondary','refresh')+button('Simulate finding','simulate-finding','primary','bolt'))}
      <section class="metrics">${stat('Unresolved findings',m.open,`${m.critical} critical · ${m.inProgress} in progress`,'assurance')}${stat('Past remediation target',m.overdue,'Targets are demonstration policy settings','clock')}${stat('Verified remediations',m.resolved,'Closed after the control passes verification','check')}${stat('Average time to resolve',duration(m.meanRemediationMinutes),'Minutes · verified findings in this session','refresh')}</section>
      ${subnav('assurance',ui.assuranceTab,[['findings','Findings',m.open],['posture','Posture'],['lifecycle','Ownership & lifecycle']])}
      ${{findings:findingsView,posture:postureView,lifecycle:lifecycleView}[ui.assuranceTab]()}`;
  }
  function findingsView() {
    const list=engine.findings.filter(f=>(ui.findingState==='All states'||(ui.findingState==='Unresolved'?unresolved(f):f.status===ui.findingState))&&(ui.findingSeverity==='All priorities'||f.severity===ui.findingSeverity)&&(ui.assuranceEnv==='all'||f.envId===ui.assuranceEnv));
    return `<section class="panel"><div class="panel-heading"><div><h2>Remediation workbench <span class="count">${list.length}</span></h2><p>Find the owner, address the cause, then verify the outcome.</p></div><div class="filter-row"><label><span class="sr-only">Finding status</span><select id="finding-state">${['Unresolved','All states','Open','In progress','Resolved','Retired'].map(s=>`<option ${ui.findingState===s?'selected':''}>${s}</option>`).join('')}</select></label><label><span class="sr-only">Finding priority</span><select id="finding-severity">${['All priorities','Critical','High','Medium'].map(s=>`<option ${ui.findingSeverity===s?'selected':''}>${s}</option>`).join('')}</select></label><label><span class="sr-only">Finding environment</span><select id="assurance-env">${envOptions(ui.assuranceEnv,true)}${engine.environments.filter(e=>e.lifecycle!=='Active').map(e=>`<option value="${e.id}" ${ui.assuranceEnv===e.id?'selected':''}>${esc(e.name)} · ${e.lifecycle}</option>`).join('')}</select></label></div></div>
      ${list.length?`<div class="table-wrap"><table class="findings-table"><thead><tr><th>Finding</th><th>Environment</th><th>Priority</th><th>Status</th><th>Owner / target</th><th>Action</th></tr></thead><tbody>${list.map(f=>`<tr><td>${findingLink(f)}</td><td><button class="text-button dark" data-action="environment" data-id="${f.envId}">${esc(engine.env(f.envId).name)}</button><small class="cell-sub">${engine.env(f.envId).provider}</small></td><td>${severity(f.severity)}</td><td>${badge(f.status)}</td><td><span class="finding-owner">${esc(f.owner)}</span><small class="cell-sub">${unresolved(f)?due(f.dueAt):f.status==='Resolved'?'Verified '+time(f.resolvedAt)+' UTC':'Archived with workload'}</small></td><td>${button('Review','finding','secondary','',`data-id="${f.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('check','No matching findings','Adjust the filters or inject a simulated finding to explore the workflow.',button('Simulate finding','simulate-finding','secondary','bolt'))}
      <div class="panel-footnote">A risk acceptance keeps the finding visible. Only successful control verification counts as remediation.</div></section>
      <div class="assurance-explainer"><span>${icon('assurance')}</span><div><h3>A signal becomes an accountable action.</h3><p>Detection creates a finding and re-evaluates access. Owners remediate it; Governance records the decision and the supporting evidence.</p></div>${button('Review risk decisions','navigate','secondary','arrow','data-page="governance/decisions"')}</div>`;
  }
  function postureView() {
    const active=activeEnvs();
    return `<div class="cloud-posture-grid">${['AWS','Azure','GCP'].map(p=>{const envs=active.filter(e=>e.provider===p),passes=envs.reduce((n,e)=>n+engine.trust(e).passed,0),total=envs.length*6;return `<article class="panel cloud-posture-card"><div>${provider(p)}<h2>${p}</h2><span>${envs.length} active workloads</span></div><strong>${total?Math.round(passes/total*100)+'%':'—'}<small> controls passing</small></strong><div class="posture-meter"><span style="width:${total?passes/total*100:0}%"></span></div><p>${passes}/${total} observed baseline controls · ${envs.filter(e=>engine.trust(e).exception).length} exceptions</p></article>`}).join('')}</div>
      <section class="panel"><div class="panel-heading"><div><h2>Control posture matrix</h2><p>Observed signals from the simulator. Evidence older than ${POLICY.signalFreshnessHours} hours fails Current signals; a scan refreshes it without repairing other controls.</p></div><div class="table-actions">${button('Advance 25 h','advance','secondary','clock','data-minutes="1500"')}${button('View baseline policy','policy-code','secondary','policies')}</div></div><div class="table-wrap"><table class="posture-table"><thead><tr><th>Environment</th>${CONTROLS.map(c=>`<th>${c.name}</th>`).join('')}<th>Last observation</th></tr></thead><tbody>${active.map(e=>`<tr><td><button class="text-button dark" data-action="environment" data-id="${e.id}">${esc(e.name)}</button><small class="cell-sub">${e.provider} · ${esc(e.owner)}</small></td>${CONTROLS.map(c=>`<td><span class="posture-cell ${e.controls[c.id]?'pass':'fail'}" aria-label="${esc(e.name)}: ${c.name} ${e.controls[c.id]?'passes':'fails'}">${icon(e.controls[c.id]?'check':'x')}<span>${e.controls[c.id]?'Pass':'Fail'}</span></span></td>`).join('')}<td><span class="cell-sub">${date(e.lastScanAt)}</span>${time(e.lastScanAt)} UTC</td></tr>`).join('')}</tbody></table></div>${active.length?'':empty('foundations','No active workloads','Provision an environment in Cloud Foundations to establish a new baseline.')}</section>`;
  }
  function lifecycleView() {
    const m=engine.assuranceMetrics();
    return `<div class="lifecycle-note"><div><b>${m.owned}/${m.active}</b><span>Active workloads with ownership controls passing</span></div><div><b>${m.reviewDue}</b><span>Ownership reviews due</span></div><div><b>${m.retired}</b><span>Workloads retired · evidence retained</span></div></div>
      <section class="panel"><div class="panel-heading"><div><h2>Workload ownership & lifecycle</h2><p>Retirement blocks new access and revokes current grants before decommissioning.</p></div></div><div class="table-wrap"><table><thead><tr><th>Workload</th><th>Accountable owner</th><th>Next review</th><th>Lifecycle</th><th>Action</th></tr></thead><tbody>${engine.environments.map(e=>`<tr><td><button class="env-link" data-action="environment" data-id="${e.id}">${provider(e.provider)}<span><b>${esc(e.name)}</b><small>${e.tier}</small></span></button></td><td>${esc(e.owner)}<small class="cell-sub">${esc(e.tags.costCenter)}</small></td><td>${e.lifecycle==='Active'?due(e.reviewAt):'—'}</td><td>${badge(e.lifecycle,e.lifecycle==='Active'?'green':'gray')}</td><td><div class="table-actions">${e.lifecycle==='Active'?button('Review owner','owner-review','secondary','',`data-id="${e.id}"`):''}${e.lifecycle!=='Retired'?button(e.lifecycle==='Active'?'Retire':'Complete retirement','lifecycle','secondary','',`data-id="${e.id}"`):auditButton(e.id)}</div></td></tr>`).join('')}</tbody></table></div></section>`;
  }
  function governance() {
    const m=engine.governanceMetrics();
    return `${pageHeader('PILLAR 04 / PROVE TRUST','Cloud Governance','Connect risk decisions, control attestations, and evidence.',button('View policy','policy-code','secondary','policies')+button('Export trust evidence','export','primary','download'))}
      ${subnav('governance',ui.governanceTab,[['overview','Overview'],['decisions','Risk & policies',m.unreviewed],['attestations','Attestations',m.reviewPending],['evidence','Evidence']])}
      ${{overview:governanceOverview,decisions:()=>riskView()+policies(true),attestations:attestationsView,evidence:()=>evidence(true)}[ui.governanceTab]()}`;
  }
  function governanceOverview() {
    const m=engine.governanceMetrics(),a=engine.assuranceMetrics(),trust=engine.metrics();
    const current=engine.attestations.filter(t=>t.status==='Current');
    return `<section class="metrics">${stat('Current attestations',`${m.current}<span>/ ${m.coverageDenominator}</span>`,'Active workloads · all six controls','governance')}${stat('Active exceptions',m.exceptions,'Scoped, approved, and time-bound','clock')}${stat('Findings without a risk decision',m.unreviewed,'Open work requiring a disposition','alert')}${stat('Evidence events',m.evidence,'One connected record across all four pillars','evidence')}</section>
      <div class="governance-grid"><section class="panel"><div class="panel-heading"><div><h2>Control assurance coverage</h2><p>Passing controls and current attestations are measured separately.</p></div></div><div class="table-wrap"><table><thead><tr><th>Baseline control</th><th>Passing</th><th>Attested</th></tr></thead><tbody>${CONTROLS.map(c=>`<tr><td>${c.name}</td><td>${activeEnvs().filter(e=>e.controls[c.id]).length} / ${activeEnvs().length}</td><td>${current.filter(t=>t.snapshot.controls[c.id]).length} / ${activeEnvs().length}</td></tr>`).join('')}</tbody></table></div><div class="panel-footnote">Demo control catalog. These counts are not compliance certification or production audit results.</div></section>
      <section class="governance-next"><span class="eyebrow">REVIEW THE DECISION</span><h2>Trust needs an accountable record.</h2><p>Preserve the rationale, the owner, and the evidence that supported the decision.</p><div class="governance-todo"><button data-action="navigate" data-page="governance/attestations"><span><b>${m.reviewPending}</b> attestations awaiting review</span>${icon('arrow')}</button><button data-action="navigate" data-page="governance/attestations"><span><b>${m.stale}</b> stale or expired records</span>${icon('arrow')}</button><button data-action="navigate" data-page="governance/decisions"><span><b>${m.riskAccepted}</b> active risk acceptances</span>${icon('arrow')}</button></div>${button('Attest a baseline','attest','demo-start','plus')}</section></div>
      <section class="panel"><div class="panel-heading"><div><h2>Outcomes from this demo session</h2><p>Calculated from current synthetic records; no organizational performance is implied.</p></div></div><div class="outcome-grid"><div><b>${trust.revoked}</b><span>Automatic access revocations</span></div><div><b>${a.resolved}</b><span>Verified remediations</span></div><div><b>${duration(a.meanRemediationMinutes)}</b><span>Average remediation minutes</span></div><div><b>${a.overdue}</b><span>Findings past their target</span></div></div></section>`;
  }
  function riskView() {
    return `<section class="panel"><div class="panel-heading"><div><h2>Risk decision register <span class="count">${engine.riskDecisions.length}</span></h2><p>Taylor Brooks · simulated risk reviewer. Acceptance requires an approved exception for the same control.</p></div>${button('Record risk decision','risk-decision','primary','plus')}</div>${engine.riskDecisions.length?`<div class="review-list">${engine.riskDecisions.map(d=>`<article class="review-item"><div><h3>${esc(engine.finding(d.findingId).title)} ${badge(d.status)}</h3><p>${esc(engine.env(d.envId).name)} · ${d.id} · ${d.findingId}</p><p class="quote"><b>${esc(d.disposition)}</b> — ${esc(d.rationale)}</p><p>${esc(d.reviewer)} · Owner: ${esc(d.owner)}${d.expiresAt?' · Acceptance ends '+date(d.expiresAt)+' '+time(d.expiresAt)+' UTC':''}</p></div><div class="review-actions">${button('View finding','finding','secondary','','data-id="'+d.findingId+'"')}${auditButton(d.envId)}</div></article>`).join('')}</div>`:empty('governance','Every finding needs a disposition','Choose remediation, or record a temporary acceptance backed by an approved, scoped exception.')}</section>`;
  }
  function attestationsView() {
    return `<section class="panel"><div class="panel-heading"><div><h2>Control attestations <span class="count">${engine.attestations.length}</span></h2><p>Owner statement → independent review → current for up to 30 days</p></div>${button('Submit attestation','attest','primary','plus')}</div>${engine.attestations.length?`<div class="table-wrap"><table><thead><tr><th>Environment / record</th><th>Attesting owner</th><th>Status</th><th>Review / validity</th><th>Action</th></tr></thead><tbody>${engine.attestations.map(a=>`<tr><td><b>${esc(engine.env(a.envId).name)}</b><small class="cell-sub">${a.id} · Policy ${a.policyVersion}</small></td><td>${esc(a.attester)}</td><td>${badge(a.status)}</td><td>${a.validUntil?date(a.validUntil):a.status==='Submitted'?'Awaiting reviewer':'New submission required'}<small class="cell-sub">${a.reviewer?esc(a.reviewer):'Taylor Brooks · review queue'}</small></td><td>${button(a.status==='Submitted'?'Review':'View record','attestation-detail',a.status==='Submitted'?'primary':'secondary','',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('governance','Passing controls are ready to attest','An owner records a baseline statement with a snapshot of the evidence. A separate demo reviewer makes the approval decision.')}
      <div class="panel-footnote">A failed control, ownership change, retirement, or expiry invalidates a current attestation. Old snapshots remain in the evidence history.</div></section>`;
  }
  function showFinding(id) {
    const f=engine.finding(id),env=engine.env(f.envId),risk=engine.riskDecisions.find(d=>d.findingId===id&&d.status==='Active');
    openDialog('Finding '+esc(f.id),`<div class="finding-detail-heading"><div>${severity(f.severity)} ${badge(f.status)}</div><h3>${esc(f.title)}</h3><p>${esc(env.name)} · ${env.provider} · ${esc(f.category)}</p></div><dl class="finding-facts"><div><dt>Accountable assignee</dt><dd>${esc(f.owner)}</dd></div><div><dt>Remediation target</dt><dd>${unresolved(f)?due(f.dueAt):f.status==='Resolved'?'Verified '+time(f.resolvedAt)+' UTC':'Archived with workload'}</dd></div><div><dt>Detected</dt><dd>${date(f.detectedAt)} · ${time(f.detectedAt)} UTC</dd></div><div><dt>Control health</dt><dd>${badge(env.controls[f.control]?'Pass':'Fail',env.controls[f.control]?'green':'red')}</dd></div></dl><div class="remediation-plan"><span class="eyebrow">REMEDIATION PLAN</span><p>${esc(f.fix)}</p><small>Source: ${f.source}. Applying a fix changes the synthetic signal and verifies the result.</small></div>${risk?`<div class="callout">${icon('governance')}<span><b>${esc(risk.disposition)}</b> · ${esc(risk.rationale)}<br>This disposition does not mark the control as passing.</span></div>`:''}${unresolved(f)?`<form id="finding-owner-form" class="inline-owner-form"><input type="hidden" name="findingId" value="${id}"><label class="field">Finding owner<input name="owner" value="${esc(f.owner)}" minlength="3" maxlength="80" required></label><label class="field">Assignment note<input name="note" placeholder="Optional handoff context" maxlength="500"></label><div data-form-error role="alert" class="form-error"></div><button class="btn secondary" type="submit">Save assignment</button></form>`:''}${f.notes.length?`<div class="finding-notes">${f.notes.map(n=>`<p><b>${time(n.at)} UTC · ${esc(n.actor)}</b><br>${esc(n.text)}</p>`).join('')}</div>`:''}`,`${auditButton(env.id)}${unresolved(f)?button('Risk decision','risk-decision','secondary','governance','data-id="'+id+'"'):''}${f.status==='Open'&&env.lifecycle==='Active'?button('Start remediation','start-remediation','primary','refresh','data-id="'+id+'"'):f.status==='In progress'&&env.lifecycle==='Active'?button('Apply fix & verify','complete-remediation','primary','check','data-id="'+id+'"'):''}`,'wide');
    ui.modal={type:'finding',id};
  }
  function showSimulate() {
    openDialog('Simulate an assurance finding',activeEnvs().length?`<p class="modal-intro">Change a posture signal to create accountable remediation work. Active access is re-evaluated in the same flow.</p><form id="simulate-form"><div class="form-grid"><label class="field full">Environment<select name="envId">${envOptions(ui.assuranceEnv)}</select></label><label class="field full">Finding to inject<select name="control">${Object.entries(FINDING_TYPES).map(([key,f])=>`<option value="${key}">${f.title} · ${f.severity}</option>`).join('')}</select></label></div><div class="callout">${icon('info')}Existing unresolved findings are updated, not duplicated. All signals are synthetic.</div><div data-form-error role="alert" class="form-error"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">Inject finding</button></div></form>`:empty('foundations','No active environments','Provision a workload in Cloud Foundations before testing assurance.'));
  }
  function showOwner(id) {
    const env=engine.env(id);
    openDialog('Review ownership',`<p class="modal-intro">${esc(env.name)} · Confirm who owns the workload and when it needs its next lifecycle review.</p><form id="owner-review-form"><input type="hidden" name="envId" value="${id}"><div class="form-grid"><label class="field full">Accountable owner<input name="owner" minlength="3" maxlength="80" value="${esc(env.owner)}" required></label><label class="field">Cost center<input name="costCenter" maxlength="40" value="${esc(env.tags.costCenter)}" required></label><label class="field">Review again in<select name="reviewDays"><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option></select></label></div><p class="form-note">Changed ownership or tags invalidate attestations based on the earlier snapshot. Existing finding assignments remain unchanged.</p><div data-form-error role="alert" class="form-error"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">Confirm ownership</button></div></form>`);
  }
  function showLifecycle(id) {
    const env=engine.env(id),target=env.lifecycle==='Active'?'Retiring':'Retired';
    openDialog(target==='Retiring'?'Begin workload retirement':'Complete simulated retirement',`<p class="modal-intro">${esc(env.name)}</p><p>${target==='Retiring'?'New access will be blocked and active sessions revoked. The workload moves to Retiring before decommissioning.':'The workload moves to Retired. Open findings are archived, and the complete history remains available.'}</p><form id="lifecycle-form"><input type="hidden" name="envId" value="${id}"><input type="hidden" name="target" value="${target}"><label class="field full lifecycle-reason">Reason<textarea name="reason" minlength="10" maxlength="500" rows="3" required placeholder="Record the business reason for retiring this workload."></textarea></label><p class="form-note">Simulation only. No real cloud resources are deleted. Archived findings are not counted as verified remediations.</p><div data-form-error role="alert" class="form-error"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">${target==='Retiring'?'Begin retirement':'Complete retirement'}</button></div></form>`);
  }
  function showRisk(id) {
    const findings=engine.findings.filter(f=>unresolved(f)&&engine.env(f.envId).lifecycle==='Active');
    openDialog('Record a risk decision',findings.length?`<p class="modal-intro">Acting as Taylor Brooks, the simulated risk reviewer. Record a reason for the disposition.</p><form id="risk-form"><div class="form-grid"><label class="field full">Finding<select name="findingId">${findings.map(f=>`<option value="${f.id}" ${f.id===id?'selected':''}>${esc(engine.env(f.envId).name)} · ${esc(f.title)}</option>`).join('')}</select></label><label class="field full">Disposition<select name="disposition"><option>Remediate</option><option>Accept temporarily</option></select></label><label class="field full">Decision rationale<textarea name="rationale" minlength="10" maxlength="500" rows="3" required placeholder="Describe the chosen action, risk, and accountable owner."></textarea></label></div><div class="callout">${icon('clock')}Temporary acceptance requires an approved networking exception for this exact nonproduction workload. Its expiry is inherited; it does not repair the finding.</div><div data-form-error role="alert" class="form-error"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">Record decision</button></div></form>`:empty('check','No unresolved findings','Simulate a finding in Cloud Assurance to demonstrate a risk decision.'));
  }
  function showAttest(id) {
    openDialog('Submit a control attestation',activeEnvs().length?`<p class="modal-intro">As the workload owner, attest that the six baseline controls have been reviewed. Submission captures the evidence; a reviewer must approve it.</p><form id="attest-form"><div class="form-grid"><label class="field full">Environment<select name="envId">${envOptions(id)}</select></label><label class="field full">Owner statement<textarea name="statement" minlength="10" maxlength="1000" rows="3" required placeholder="I reviewed the baseline controls, ownership, and supporting evidence for this workload."></textarea></label></div><div class="callout">${icon('policies')}All six controls must pass. A time-bound exception cannot be attested as a healthy baseline.</div><div data-form-error role="alert" class="form-error"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">Submit for review</button></div></form>`:empty('foundations','No active workloads','Provision an environment before submitting a baseline attestation.'));
  }
  function showAttestation(id) {
    const a=engine.attestations.find(a=>a.id===id);if(!a)throw new Error('Choose an existing attestation.');
    const env=engine.env(a.envId);
    openDialog('Control attestation '+a.id,`<div class="finding-detail-heading"><div>${badge(a.status)}</div><h3>${esc(env.name)}</h3><p>Attested by ${esc(a.attester)} · ${date(a.submittedAt)} · Policy ${a.policyVersion}</p></div><blockquote class="attestation-statement">${esc(a.statement)}</blockquote><div class="table-wrap"><table><thead><tr><th>Control</th><th>Captured state</th><th>Current state</th></tr></thead><tbody>${CONTROLS.map(c=>`<tr><td>${c.name}</td><td>${badge(a.snapshot.controls[c.id]?'Pass':'Fail',a.snapshot.controls[c.id]?'green':'red')}</td><td>${badge(env.controls[c.id]?'Pass':'Fail',env.controls[c.id]?'green':'red')}</td></tr>`).join('')}</tbody></table></div><p class="form-note">${a.evidenceIds.length} supporting event references captured. Snapshot owner: ${esc(a.snapshot.owner)}. Current owner: ${esc(env.owner)}. Lifecycle: ${env.lifecycle}.</p>${a.reviewRationale?`<div class="callout">${icon('governance')}<span><b>${esc(a.reviewer)}</b><br>${esc(a.reviewRationale)}${a.validUntil?'<br>Recorded validity end: '+date(a.validUntil):''}</span></div>`:''}${a.status==='Submitted'?`<form id="attestation-review-form"><input type="hidden" name="id" value="${a.id}"><label class="field">Reviewer rationale<textarea name="rationale" minlength="10" maxlength="500" rows="2" required placeholder="Record the basis for your review decision."></textarea></label><p class="form-note">Acting as Taylor Brooks. Changed evidence makes a submission stale and prevents approval.</p><div data-form-error role="alert" class="form-error"></div><div class="form-actions"><button type="submit" name="decision" value="reject" class="btn secondary">Reject</button><button type="submit" name="decision" value="approve" class="btn primary">Approve attestation</button></div></form>`:''}`,auditButton(env.id),'wide');
    ui.modal={type:'attestation',id};
  }
  function showPolicy(){openDialog('Shared trust policy',`<p class="modal-intro">The demo engine uses these policy settings across all four pillars. The definition can be exported as part of the evidence bundle.</p><pre class="policy-code"><code>${esc(JSON.stringify(engine.policyDefinition(),null,2))}</code></pre>`,button('Close','close'),'wide');}
  const actions={
    finding:id=>showFinding(id),
    scan:()=>{const s=engine.runScan();render();toast(`Observed ${s.environmentIds.length} active workloads. Findings and access were re-evaluated.`);},
    'simulate-finding':()=>showSimulate(),
    'start-remediation':id=>{engine.startRemediation(id);render();showFinding(id);toast('Remediation started. The finding remains open until verification.');},
    'complete-remediation':id=>{engine.completeRemediation(id);render();showFinding(id);toast('Fix verified. Revoked access remains closed.');},
    'owner-review':id=>showOwner(id),lifecycle:id=>showLifecycle(id),
    'risk-decision':id=>showRisk(id),attest:id=>showAttest(id),'attestation-detail':id=>showAttestation(id),'policy-code':()=>showPolicy()
  };
  function action(name,id){if(!actions[name])return false;actions[name](id);return true;}
  function submit(event){
    const form=event.target,known=['simulate-form','finding-owner-form','owner-review-form','lifecycle-form','risk-form','attest-form','attestation-review-form'];
    if(!known.includes(form.id))return false;
    event.preventDefault();const data=Object.fromEntries(new FormData(form));
    try{
      if(form.id==='simulate-form'){engine.changeControl(data.envId,data.control,false);ui.assuranceEnv='all';ui.findingState='Unresolved';ui.findingSeverity='All priorities';closeDialog();navigate('assurance/findings');render();showFinding(engine.findings.find(f=>f.envId===data.envId&&f.control===data.control&&unresolved(f)).id);}
      else if(form.id==='finding-owner-form'){engine.assignFinding(data.findingId,data.owner,data.note);render();showFinding(data.findingId);toast('Finding owner updated.');}
      else if(form.id==='owner-review-form'){engine.updateOwner(data.envId,{...data,reviewDays:Number(data.reviewDays)});closeDialog();navigate('assurance/lifecycle');render();toast('Ownership and next review recorded.');}
      else if(form.id==='lifecycle-form'){engine.changeLifecycle(data.envId,data.target,data.reason);closeDialog();navigate('assurance/lifecycle');render();toast('Lifecycle updated. Access and attestations were re-evaluated.');}
      else if(form.id==='risk-form'){engine.recordRiskDecision(data);closeDialog();navigate('governance/decisions');render();toast('Risk decision recorded. The finding remains visible.');}
      else if(form.id==='attest-form'){const a=engine.submitAttestation(data);closeDialog();navigate('governance/attestations');render();showAttestation(a.id);}
      else if(form.id==='attestation-review-form'){engine.reviewAttestation(data.id,event.submitter?.value==='approve',data.rationale);render();showAttestation(data.id);toast('Attestation review recorded.');}
    }catch(error){form.querySelector('[data-form-error]').textContent=error.message;}
    return true;
  }
  function change(target){const fields={'finding-state':'findingState','finding-severity':'findingSeverity','assurance-env':'assuranceEnv'};if(!fields[target.id])return false;ui[fields[target.id]]=target.value;render();document.getElementById(target.id)?.focus();return true;}
  function refreshModal(){if(ui.modal?.type==='finding')showFinding(ui.modal.id);if(ui.modal?.type==='attestation')showAttestation(ui.modal.id);}
  return {assurance,governance,showFinding,showAttestation,action,submit,change,refreshModal};
}
